import * as React from "react"
import { Check, ChevronDown, Globe } from "lucide-react"
import * as CountryFlags from "country-flag-icons/react/3x2"

import { cn } from "@/lib/utils"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

import {
  PHONE_COUNTRY_OPTIONS,
  type PhoneCountryOption,
} from "./phone-countries"

const DEFAULT_COUNTRY_OPTIONS = PHONE_COUNTRY_OPTIONS
type FlagComponent = React.ComponentType<React.SVGProps<SVGSVGElement>>

const COUNTRY_FLAG_COMPONENTS = CountryFlags as Record<string, FlagComponent>

export interface PhoneInputProps
  extends Omit<React.ComponentProps<"input">, "className"> {
  className?: string
  inputClassName?: string
  label?: string
  helperText?: string
  error?: string
  country?: string
  defaultCountry?: string
  countryOptions?: PhoneCountryOption[]
  onCountryChange?: (country: PhoneCountryOption) => void
}

const getCountryCodeFromFlagEmoji = (flag: string): string | null => {
  const symbols = Array.from(flag)
  if (symbols.length !== 2) {
    return null
  }

  const letters = symbols.map((symbol) => {
    const codePoint = symbol.codePointAt(0)
    if (!codePoint || codePoint < 0x1f1e6 || codePoint > 0x1f1ff) {
      return null
    }
    return String.fromCharCode(codePoint - 0x1f1e6 + 65)
  })

  if (letters.some((letter) => letter === null)) {
    return null
  }

  return letters.join("")
}

const FlagIcon = ({
  flag,
  className,
}: {
  flag: string
  className?: string
}) => {
  const countryCode = React.useMemo(
    () => getCountryCodeFromFlagEmoji(flag),
    [flag]
  )
  const SvgFlag = countryCode ? COUNTRY_FLAG_COMPONENTS[countryCode] : undefined

  if (SvgFlag) {
    return (
      <SvgFlag
        aria-hidden="true"
        className={cn("h-3.5 w-5 shrink-0 rounded-[2px] object-cover", className)}
      />
    )
  }

  return (
    <span aria-hidden="true" className={className}>
      {flag}
    </span>
  )
}

const PhoneInput = React.forwardRef<HTMLInputElement, PhoneInputProps>(
  (
    {
      className,
      inputClassName,
      label = "Phone number",
      helperText,
      error,
      country,
      defaultCountry,
      countryOptions = DEFAULT_COUNTRY_OPTIONS,
      onCountryChange,
      disabled,
      type = "tel",
      onFocus,
      onBlur,
      placeholder = "Enter phone number",
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false)
    const [isInputFocused, setIsInputFocused] = React.useState(false)
    const [uncontrolledCountry, setUncontrolledCountry] = React.useState(
      defaultCountry
    )

    const selectedCountryValue = country ?? uncontrolledCountry

    const selectedCountry = React.useMemo(
      () =>
        countryOptions.find((option) => option.value === selectedCountryValue),
      [countryOptions, selectedCountryValue]
    )

    const handleCountrySelect = React.useCallback(
      (option: PhoneCountryOption) => {
        if (country === undefined) {
          setUncontrolledCountry(option.value)
        }
        onCountryChange?.(option)
        setOpen(false)
      },
      [country, onCountryChange]
    )

    const isAriaInvalid =
      props["aria-invalid"] === true || props["aria-invalid"] === "true"
    const hasError = Boolean(error) || isAriaInvalid
    const isActive = open || isInputFocused

    return (
      <div className={cn("flex w-full flex-col items-start gap-1", className)}>
        {label ? (
          <p className="w-full text-[14px] font-medium leading-[20px] text-black">
            {label}
          </p>
        ) : null}

        <div
          className={cn(
            "flex h-10 w-full items-stretch overflow-hidden rounded-[8px] border bg-white transition-colors",
            disabled
              ? "border-[#e6e6e6] bg-[#f2f2f2]"
              : hasError
                ? "border-[#ff3b30]"
                : isActive
                  ? "border-[#1d1c20]"
                  : "border-[#e6e6e6]"
          )}
        >
          <Popover
            open={open}
            onOpenChange={(nextOpen) => {
              if (disabled) {
                return
              }
              setOpen(nextOpen)
            }}
          >
            <PopoverTrigger asChild>
              <button
                type="button"
                disabled={disabled}
                aria-label="Select country"
                className={cn(
                  "flex h-full shrink-0 items-center gap-1 px-2 text-[14px] leading-[20px] outline-none transition-colors",
                  selectedCountry
                    ? isActive
                      ? "bg-white"
                      : "bg-[#fafafa]"
                    : "bg-white",
                  disabled && "bg-[#f2f2f2] text-[#b3b3b3]"
                )}
              >
                {selectedCountry ? (
                  <>
                    <FlagIcon flag={selectedCountry.flag} />
                    <span className="font-normal text-black">
                      {selectedCountry.label}
                    </span>
                  </>
                ) : (
                  <Globe className="h-4 w-4 text-[#adacb0]" />
                )}
                <ChevronDown className="h-4 w-4 text-[#adacb0]" />
              </button>
            </PopoverTrigger>

            <PopoverContent
              align="start"
              sideOffset={8}
              className="w-[240px] rounded-[8px] border border-[#e6e6e6] bg-white p-0 shadow-[0px_2px_4px_0px_rgba(19,25,39,0.12),0px_4px_4px_0px_rgba(19,25,39,0.08)]"
            >
              <Command
                className={cn(
                  "rounded-[8px] bg-white",
                  "[&_[cmdk-input-wrapper]]:mx-2 [&_[cmdk-input-wrapper]]:mb-1 [&_[cmdk-input-wrapper]]:mt-2 [&_[cmdk-input-wrapper]]:h-8 [&_[cmdk-input-wrapper]]:rounded-[4px] [&_[cmdk-input-wrapper]]:border [&_[cmdk-input-wrapper]]:border-[#e6e6e6] [&_[cmdk-input-wrapper]]:px-3",
                  "[&_[cmdk-input-wrapper]_svg]:mr-2 [&_[cmdk-input-wrapper]_svg]:h-4 [&_[cmdk-input-wrapper]_svg]:w-4 [&_[cmdk-input-wrapper]_svg]:text-[#adacb0]",
                  "[&_[cmdk-input]]:h-full [&_[cmdk-input]]:py-0 [&_[cmdk-input]]:text-[14px] [&_[cmdk-input]]:leading-[20px] [&_[cmdk-input]]:text-black [&_[cmdk-input]]:placeholder:text-[#adacb0]"
                )}
              >
                <CommandInput placeholder="Search country" />
                <CommandList className="max-h-56 px-1 pb-1">
                  <CommandEmpty className="px-3 py-2 text-left text-[12px] leading-[16px] text-[#7f7d83]">
                    No country found
                  </CommandEmpty>
                  <CommandGroup className="p-0">
                    {countryOptions.map((option) => {
                      const isSelected = option.value === selectedCountryValue
                      const optionName = option.name || option.label

                      return (
                        <CommandItem
                          key={option.value}
                          value={`${option.label} ${optionName} ${option.dialCode}`}
                          onSelect={() => handleCountrySelect(option)}
                          className={cn(
                            "flex w-full cursor-pointer items-center gap-2 rounded-[4px] px-3 py-2 text-[14px] leading-[20px] text-black",
                            "data-[selected=true]:bg-[#fafafa] data-[selected=true]:text-black",
                            isSelected && "bg-[#fafafa]"
                          )}
                        >
                          <FlagIcon flag={option.flag} />
                          <span className="min-w-0 flex-1 truncate">{optionName}</span>
                          {option.dialCode ? (
                            <span className="text-[#7f7d83]">{option.dialCode}</span>
                          ) : null}
                          <Check
                            className={cn(
                              "h-4 w-4 text-[#1d1c20]",
                              isSelected ? "opacity-100" : "opacity-0"
                            )}
                          />
                        </CommandItem>
                      )
                    })}
                  </CommandGroup>
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>

          <div
            className={cn(
              "flex min-w-0 flex-1 items-center gap-2 border-l border-[#e6e6e6] bg-white px-3 py-2",
              disabled && "bg-[#f2f2f2]"
            )}
          >
            {selectedCountry?.dialCode ? (
              <span className="shrink-0 text-[14px] leading-[20px] text-[#7f7d83]">
                {selectedCountry.dialCode}
              </span>
            ) : null}
            <input
              ref={ref}
              disabled={disabled}
              placeholder={placeholder}
              onFocus={(event) => {
                setIsInputFocused(true)
                onFocus?.(event)
              }}
              onBlur={(event) => {
                setIsInputFocused(false)
                onBlur?.(event)
              }}
              className={cn(
                "h-full w-full min-w-0 border-0 bg-transparent p-0 text-[14px] leading-[20px] text-black outline-none placeholder:text-[#adacb0]",
                disabled &&
                  "cursor-not-allowed text-[#9ca3af] placeholder:text-[#b3b3b3]",
                inputClassName
              )}
              type={type}
              {...props}
            />
          </div>
        </div>

        {error ? (
          <p className="w-full text-[12px] leading-[16px] text-[#ff3b30]">{error}</p>
        ) : helperText ? (
          <p className="w-full text-[12px] leading-[16px] text-[#7f7d83]">
            {helperText}
          </p>
        ) : null}
      </div>
    )
  }
)

PhoneInput.displayName = "PhoneInput"

export { PhoneInput, DEFAULT_COUNTRY_OPTIONS }
export type { PhoneCountryOption }
